import {dimensions,money,validateScenario,initialState,commit,artifactBody,badges,outcome} from './engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let scenario,state,view='claim',selected=null,allocation={},draft='',feedback=null,doc=null,error='',storageOkay=true;
const KEY='stop-the-meter-session-v1',totalXP=()=>scenario.stages.reduce((n,t)=>n+t.xp,0),wordCount=t=>t.trim().split(/\s+/).filter(Boolean).length;
function save(){try{localStorage.setItem(KEY,JSON.stringify({scenario,state,draft,feedback:!!feedback}));}catch{storageOkay=false;}}
function toast(text){const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),3000);}
async function boot(){try{scenario=validateScenario(await(await fetch('./scenario.json')).json());state=initialState(scenario);try{const raw=localStorage.getItem(KEY);if(raw){const saved=JSON.parse(raw);validateScenario(saved.scenario);let recovered=initialState(saved.scenario);for(const h of saved.state.history)recovered=commit(saved.scenario,recovered,h.answer);recovered.read=Array.isArray(saved.state.read)?saved.state.read.filter(x=>typeof x==='string'):[];scenario=saved.scenario;state=recovered;draft=typeof saved.draft==='string'?saved.draft:'';feedback=saved.feedback?state.history.at(-1):null;}}catch{toast('Saved progress could not be restored. A fresh claim is ready.');}render();registerTools();}catch(e){$('#app').innerHTML=`<main class="loading"><h1>The claim could not open</h1><p>${esc(e.message)}</p><p>Run this project with the local server in the README, then reload.</p></main>`;}}
function nav(){return `<nav class="sidebar" aria-label="Claim desktop"><p class="side-caption">YOUR WORKSPACE</p>${[['claim','◈','Live claim'],['evidence','▤','Evidence file'],['timeline','◷','Claim timeline'],['report','◇','Coaching report']].map(([id,icon,name])=>`<button data-view="${id}" class="${view===id?'active':''}" ${id==='report'&&!state.complete?'disabled':''} ${view===id?'aria-current="page"':''}>${icon} &nbsp; ${name}</button>`).join('')}<div class="side-bottom"><button data-view="guide">ⓘ &nbsp; Field guide</button><button data-view="author">⚙ &nbsp; Scenario studio</button><button id="restart">↻ &nbsp; Restart claim</button><p>Fictional training file<br>England & Wales<br>Saved on this browser.</p></div></nav>`;}
function scores(){return `<div class="card scores"><h3>Handling score <span class="hint">${state.scores.reduce((a,b)=>a+b,0)} / 500</span></h3>${dimensions.map((d,i)=>`<div class="score-row"><div class="score-label"><span>${d}</span><b>${state.scores[i]}</b></div><div class="progress-track" role="meter" aria-label="${d}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${state.scores[i]}"><div class="progress-fill" style="width:${state.scores[i]}%"></div></div></div>`).join('')}</div>`;}
function rail(){return `<aside class="rail"><div class="meter"><span class="live">${state.index>=scenario.stages.length-2?'HIRE PERIOD CLOSED':'THE METER IS RUNNING'}</span><div class="amount">${money(state.day*scenario.dailyRate)}</div><p>Potential hire exposure · excludes extras</p><div class="meter-line"><span>Simulated day ${state.day}</span><b>${money(scenario.dailyRate)} / day</b></div></div>${scores()}<p class="rail-note">The exposure is not your score. Time advances with decisions, never while you read.<br><br>Earn up to ${totalXP()} XP through evidence and sound judgement.</p></aside>`;}
function docLink(id){const a=scenario.artifacts.find(a=>a.id===id);return `<button class="document-link" data-doc="${esc(id)}"><span class="doc-icon">FILE</span><span>${esc(a.title)}<small>${esc(a.kind)} · ${state.read.includes(id)?'Reviewed':'Ready to review'}</small></span></button>`;}
function claim(){if(feedback)return feedbackView();if(state.complete)return report();const t=scenario.stages[state.index];return `<div class="layout"><section class="card"><div class="card-head"><h3>Your next move</h3><span class="tag">${String(state.index+1).padStart(2,'0')} / ${scenario.stages.length}</span></div><div class="card-body"><div class="steps" aria-label="${state.index} decisions completed">${scenario.stages.map((_,i)=>`<span class="${i<state.index?'done':i===state.index?'current':''}"></span>`).join('')}</div>${state.index===0?`<div class="brief"><div><label>CLAIMANT</label>${esc(scenario.claimant)}</div><div><label>VEHICLE</label>${esc(scenario.vehicle)}</div><div><label>INCIDENT</label>Rear-end collision · Monday 08:15</div><div><label>NOTIFICATION</label>Hire commenced · 14:30</div></div>`:''}<div class="decision"><p class="eyebrow">${esc(t.phase)}</p><h2 id="decision-title" tabindex="-1">${esc(t.title)}</h2><p>${esc(t.prompt)}</p>${t.id==='bhr'&&!state.flags.includes('finance')?'<p class="note">Your financial enquiry left a gap. Use the provisional assumption that impecuniosity is not established for this exercise, then revisit the evidence at negotiation.</p>':''}<details ${state.index===0?'open':''}><summary class="hint">Evidence for this decision (${t.docs.length})</summary>${t.docs.map(docLink).join('')}</details>${input(t)}${error?`<p class="error" role="alert">${esc(error)}</p>`:''}<div class="actions"><span class="hint">${t.type==='multi'?'Select all that apply.':t.type==='note'?'Topic coverage is checked; your coach assesses reasoning.':'Your choice becomes part of the claim file.'}</span><button class="primary" id="commit">${t.type==='note'?'Close claim & reveal report':'Commit decision'}</button></div></div></div></section>${rail()}</div>`;}
function input(t){if(t.type==='choice'||t.type==='multi')return `<div role="group" aria-label="Decision options">${t.options.map((o,i)=>{const yes=t.type==='multi'?(selected||[]).includes(o.id):selected===o.id;return `<button class="option ${yes?'selected':''}" data-option="${esc(o.id)}" aria-pressed="${yes}"><span class="letter">${t.type==='multi'?(yes?'✓':'+'):String.fromCharCode(65+i)}</span><span>${esc(o.label)}</span></button>`}).join('')}</div>`;if(t.type==='allocation')return t.issues.map(i=>`<label class="allocation"><span>${esc(i.label)}</span><select data-issue="${esc(i.id)}" aria-label="Position on ${esc(i.label)}"><option value="">Choose position</option>${['Accept','Challenge','Investigate'].map(x=>`<option ${allocation[i.id]===x?'selected':''}>${x}</option>`).join('')}</select></label>`).join('');return `<label class="field" for="strategy-note">Your strategy and reasoning</label><textarea id="strategy-note" maxlength="3000" placeholder="State the evidence, your position, and the next action…">${esc(draft)}</textarea><p class="hint"><span id="word-count">${wordCount(draft)}</span> / 150 words · minimum 30</p><p class="hint">Cover: ${t.rubric.map(r=>esc(r.label)).join(' · ')}</p>`;}
function feedbackView(){const r=feedback;return `<div class="layout"><section class="card"><div class="card-head"><h3>Decision debrief</h3><span class="xp">+${r.xp} XP</span></div><div class="card-body"><p class="eyebrow">${esc(r.title)}</p><h2>${r.quality>=.8?'A strong foundation':r.quality>=.4?'Some useful judgement':'A chance to improve'}</h2><p class="note">${esc(r.label)}</p><div class="feedback" role="status"><h3>What happened</h3><p>${esc(r.feedback)}</p><div class="delta">${r.score.map((n,i)=>n?`<span>${dimensions[i]} ${n>0?'+':''}${n}</span>`:'').join('')}</div></div><div class="timeline-entry"><span class="day-badge">DAY ${r.dayBefore}<br>to ${r.dayAfter}</span><div><h3>${r.days?`${r.days} simulated days passed`:'No additional time passed'}</h3><p>${r.extraDays?`${r.extraDays} days were added by this decision: ${money(r.extraDays*scenario.dailyRate)} potential hire exposure. `:''}${r.days-r.extraDays?`${r.days-r.extraDays} days reflect the scenario’s underlying progression.`:''}</p></div></div><div class="actions"><span class="hint">Handling judgement, not a court outcome.</span><button class="primary" id="continue">${state.complete?'Open coaching report':'Continue claim'}</button></div></div></section>${rail()}</div>`;}
function evidence(){const available=scenario.artifacts.filter(a=>a.unlock<=Math.min(state.index,scenario.stages.length-1));if(doc){const a=available.find(a=>a.id===doc);if(!a){doc=null;return evidence();}return `<button class="back" id="back-evidence">Back to evidence file</button><section class="card document"><p class="eyebrow">FICTIONAL CLAIM ARTEFACT / ${esc(a.kind)}</p><h2>${esc(a.title)}</h2><div class="doc-meta">${esc(a.from)} · ${esc(scenario.claimRef)}</div>${esc(artifactBody(a,{...state,rate:scenario.dailyRate}))}</section><div class="actions"><span class="hint">Recorded as reviewed</span><button class="primary" data-view="claim">Return to decision</button></div>`;}return `<h2>Evidence file</h2><p class="subtitle">${available.length} available documents. New material arrives as the claim progresses.</p><div class="doc-grid" style="margin-top:20px">${available.map(a=>docLink(a.id)).join('')}</div><p class="hint">All people, providers, financial details and rate reports are fictional.</p>`;}
function timeline(){return `<section class="card"><div class="card-head"><h3>Claim chronology</h3><span class="tag">Day ${state.day}</span></div><div class="card-body"><div class="timeline-entry"><span class="day-badge">DAY 1</span><div><h3>Hire commences</h3><p>FNOL received. Opening hire exposure: ${money(scenario.dailyRate)}.</p></div></div>${state.history.map(r=>`<div class="timeline-entry"><span class="day-badge">DAY ${r.dayAfter}</span><div><h3>${esc(r.title)}</h3><p>${esc(r.label)}</p><span class="tag">${r.extraDays?'+'+r.extraDays+' delay days':'Planned progression'} · ${money(r.dayAfter*scenario.dailyRate)} hire</span><details><summary class="hint">Coaching feedback</summary><p>${esc(r.feedback)}</p></details></div></div>`).join('')}${!state.history.length?'<p class="empty">Your decisions and their consequences will appear here.</p>':''}</div></section>`;}
function report(){if(!state.complete)return '<p class="empty">Complete the claim to reveal your report.</p>';const result=outcome(state),delay=state.history.reduce((n,r)=>n+r.extraDays,0),weak=state.history.filter(r=>r.quality<.8),note=state.history.at(-1);return `<section class="report-hero"><p class="eyebrow">MISSION COMPLETE / COACHING REPORT</p><h2>${esc(result.title)}</h2><p>${esc(result.body)}</p><div class="summary-stats"><div><small>Handling score</small><span class="report-number">${state.scores.reduce((a,b)=>a+b,0)}</span> / 500</div><div><small>Experience earned</small><span class="report-number">${state.xp}</span> / ${totalXP()} XP</div><div><small>Hire + claimed extras</small><span class="report-number">${money(state.day*scenario.dailyRate+390)}</span></div></div></section><div class="toolbar"><button class="primary" id="download-report">Download coaching report</button><button class="secondary" id="print-report">Print / save PDF</button><button class="secondary" id="replay">Replay the claim</button></div><div class="report-grid" style="margin-top:24px"><div>${scores()}<section class="card card-body" style="margin-top:20px"><h3>Your badges</h3>${badges(state).map(x=>`<div class="badge ${x.earned?'':'locked'}"><strong>${x.earned?'✓':'◇'} ${esc(x.name)}</strong><p class="hint" style="margin:6px 0 0">${esc(x.why)}</p></div>`).join('')}</section></div><section class="card card-body"><p class="eyebrow">WHAT DROVE YOUR FILE?</p><h2>${delay} additional simulated days</h2><p>Your route took ${state.day} days. Decision delays added ${money(delay*scenario.dailyRate)} in potential hire exposure.</p><div class="table-wrap"><table><thead><tr><th>Component</th><th>Exposure</th></tr></thead><tbody><tr><td>Underlying ${state.day-delay} simulated days</td><td>${money((state.day-delay)*scenario.dailyRate)}</td></tr><tr><td>Decision-related delay</td><td>${money(delay*scenario.dailyRate)}</td></tr><tr><td>Claimed delivery / collection</td><td>£120</td></tr><tr><td>Claimed waiver</td><td>£270</td></tr><tr><th>Total submitted</th><th>${money(state.day*scenario.dailyRate+390)}</th></tr></tbody></table></div><p class="hint">Potential exposure is not proven recoverable loss. No automatic disallowance of these days or extras is assumed.</p><h3>Next coaching priorities</h3>${weak.length?weak.slice(0,3).map(r=>`<p><strong>${esc(r.title)}</strong><br>${esc(r.feedback)}</p>`).join(''):'<p>You built a balanced file. On replay, explore how a different repair chronology or evidence gap changes your strategy.</p>'}</section></div><section class="card card-body" style="margin-top:24px"><p class="eyebrow">FILE RATIONALE</p><h2>Your strategy, then the model</h2><p class="note">${esc(state.note)}</p><p class="hint">Topic coverage: ${note.coverage.length} / ${scenario.stages.at(-1).rubric?.length||7}. Keyword checks award coverage XP only. They cannot judge the quality, correctness or consistency of your reasoning.</p><details><summary>Compare with the model strategy</summary><p>${esc(scenario.modelNote)}</p></details><h3 style="margin-top:24px">Discuss with your coach</h3>${(scenario.coaching||[]).map(x=>`<p>• ${esc(x)}</p>`).join('')}</section><section class="card card-body" style="margin-top:24px"><h2>Your decision review</h2>${state.history.map((r,i)=>`<details style="margin:16px 0"><summary>${i+1}. ${esc(r.title)} · ${r.xp} XP</summary><p>${esc(r.label)}</p><p>${esc(r.feedback)}</p>${r.type==='allocation'?`<p class="hint">Model allocation: ${scenario.stages[i].issues.map(x=>esc(x.label)+': '+x.answer).join('; ')}.</p>`:''}</details>`).join('')}</section><p class="rail-note" style="margin-top:20px">Need · Type · Period · Rate · Impecuniosity · Mitigation.<br>Identify → Intervene → Evidence → Monitor → Reassess.</p>`;}
function guide(){return `<section class="card card-body"><p class="eyebrow">CLAIMS ACADEMY / FIELD GUIDE</p><h2>Control the claim while the meter is running.</h2><p>Read the evidence, choose an action and review its consequences. Time advances only when you commit a decision. Poor handling can create delay, evidence gaps or customer harm. Exposure alone never determines your score.</p><h3>The credit hire control wheel</h3><div class="brief">${[['N','Need','Was replacement mobility reasonably required?'],['T','Type','Was this a reasonable replacement vehicle?'],['P','Period','What does the actual chronology support?'],['R','Rate','Which comparable evidence is useful?'],['I','Impecuniosity','What do the full financial circumstances establish?'],['M','Mitigation','What reasonable opportunities were available?']].map(([l,t,d])=>`<div><span class="tag">${l}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div><h3>Scoring is about judgement</h3><p>Each dimension starts at 50 and stays within 0–100. The total is out of 500. Decisions separately award up to ${totalXP()} XP. Multiple-selection tasks subtract credit for incorrect inclusions. The final note uses a topic-coverage check, not AI assessment.</p><h3>Training scope</h3><p>This fictional prototype follows the supplied module for England and Wales. It does not determine legal entitlement or a settlement figure. Your technical team should validate the scenario before assessed use.</p><h3>Reference material</h3><div class="source-links">${(scenario.sources||[]).filter(s=>/^https:\/\//.test(s.url)).map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a></p>`).join('')}</div><p class="hint">Background checked 29 September 2026. The supplied module is the design source; these fictional rates are not market quotations.</p></section>`;}
function author(){return `<section class="card card-body"><p class="eyebrow">SCENARIO STUDIO</p><h2>A reusable training file</h2><p>Edit on this browser or export JSON for your learning team. Applying changes starts a fresh attempt. The original scenario remains available.</p><div class="brief"><label class="field">Module title<input id="config-title" type="text" value="${esc(scenario.title)}"></label><label class="field">Daily hire rate (£)<input id="config-rate" type="number" min="1" max="10000" value="${scenario.dailyRate}"></label></div><p class="hint">A rate change updates the meter. Update any amounts written into questions and artefacts too.</p><label class="field" for="config-json">Full scenario content</label><textarea id="config-json" spellcheck="false" style="min-height:320px;font-family:monospace;font-size:.8125rem">${esc(JSON.stringify(scenario,null,2))}</textarea><p class="hint">Documents, unlock stages, decisions, scores, delays, flags and coaching. The title and rate fields override those values in the JSON.</p><div id="author-error" role="alert"></div><div class="toolbar"><button id="apply-config" class="primary">Validate & apply</button><button id="export-config" class="secondary">Export scenario</button><label class="secondary" style="cursor:pointer">Import JSON<input id="import-config" type="file" accept=".json,application/json" class="sr-only"></label><button id="restore-config" class="secondary">Restore original scenario</button></div></section>`;}
function render(){const focus=document.activeElement?.dataset?.option;$('#app').innerHTML=`<header class="topbar"><b>◷ &nbsp; CLAIMS ACADEMY</b><span>Single-player simulation / 20–30 minutes</span><b class="xp">${state.xp} XP</b></header><div class="shell">${nav()}<main id="main" class="workspace"><div class="heading"><div><p class="eyebrow">CREDIT HIRE / MISSION 01</p><h1>${esc(scenario.title)}</h1><p class="subtitle">${esc(scenario.claimRef)} · ${esc(scenario.claimant)} · Motor claim</p></div><span class="pill green">${state.complete?'Claim complete':'Decision '+Math.min(state.index+1,scenario.stages.length)+' of '+scenario.stages.length}</span></div>${!storageOkay?'<p class="error">Browser storage is unavailable. Keep this page open and download your final report.</p>':''}${view==='claim'?claim():view==='evidence'?evidence():view==='timeline'?timeline():view==='report'?report():view==='guide'?guide():author()}<div class="toolbar" style="margin-top:28px"><button class="back" data-view="guide">Field guide</button><button class="back" data-view="author">Scenario studio</button><button class="back" id="mobile-restart">Restart claim</button></div></main></div><dialog class="modal" id="confirm-dialog"><h2>Start a fresh claim?</h2><p>This replaces the attempt saved on this browser. Download your report first if you want to keep it.</p><div class="actions"><button class="secondary" id="cancel-reset">Keep current claim</button><button class="primary" id="confirm-reset">Start fresh</button></div></dialog>`;bind();if(focus)[...document.querySelectorAll('[data-option]')].find(el=>el.dataset.option===focus)?.focus();}
function navigate(v){view=v;error='';doc=null;render();}
function reset(s=scenario){scenario=s;state=initialState(s);feedback=null;draft='';selected=null;allocation={};error='';view='claim';doc=null;save();render();}
function confirmReset(s=scenario){$('#confirm-dialog').showModal();$('#cancel-reset').onclick=()=>$('#confirm-dialog').close();$('#confirm-reset').onclick=()=>reset(s);}
function submit(answer){state=commit(scenario,state,answer);feedback=state.history.at(-1);selected=null;allocation={};error='';save();render();$('#main').scrollIntoView({block:'start'});}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function reportText(){return `# Credit Hire: ${scenario.title}\n\n${scenario.claimRef} — ${scenario.claimant}\n\n${outcome(state).title}\n${outcome(state).body}\n\nScore: ${state.scores.reduce((a,b)=>a+b,0)}/500 | XP: ${state.xp}/${totalXP()}\n${dimensions.map((d,i)=>`${d}: ${state.scores[i]}/100`).join('\n')}\n\nHire: ${state.day} days × ${money(scenario.dailyRate)} = ${money(state.day*scenario.dailyRate)}\nClaimed extras: £390\nTotal claimed: ${money(state.day*scenario.dailyRate+390)} (not agreed settlement)\n\nBadges: ${badges(state).filter(b=>b.earned).map(b=>b.name).join(', ')||'None yet'}\n\n## Your strategy\n${state.note}\n\nNote scoring checks topic coverage only, not correctness or reasoning.\n\n## Model strategy\n${scenario.modelNote}\n\n## Decision review\n${state.history.map((r,i)=>`\n${i+1}. ${r.title} — ${r.xp} XP\n${r.label}\n${r.feedback}\nDay ${r.dayBefore} to ${r.dayAfter}; ${r.extraDays} additional days.\n`).join('\n')}\n## Coach discussion\n${(scenario.coaching||[]).join('\n')}\n\nFictional training prototype. Technical validation required before assessed use.\n`;}
function readEditor(){const s=JSON.parse($('#config-json').value);s.title=$('#config-title').value;s.dailyRate=Number($('#config-rate').value);return validateScenario(s);}
function authorError(e){$('#author-error').innerHTML=`<p class="error">${esc(e.message)}</p>`;}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));document.querySelectorAll('[data-doc]').forEach(b=>b.onclick=()=>{doc=b.dataset.doc;view='evidence';if(!state.read.includes(doc))state.read.push(doc);save();render();});document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{if(scenario.stages[state.index].type==='multi'){selected=selected||[];selected=selected.includes(b.dataset.option)?selected.filter(x=>x!==b.dataset.option):[...selected,b.dataset.option];}else selected=b.dataset.option;error='';render();});document.querySelectorAll('[data-issue]').forEach(el=>el.onchange=()=>allocation[el.dataset.issue]=el.value);
 if($('#strategy-note'))$('#strategy-note').oninput=e=>{draft=e.target.value;$('#word-count').textContent=wordCount(draft);save();};
 if($('#commit'))$('#commit').onclick=()=>{try{const t=scenario.stages[state.index];submit(t.type==='note'?draft:t.type==='allocation'?allocation:selected);}catch(e){error=e.message;render();}};
 if($('#continue'))$('#continue').onclick=()=>{feedback=null;if(state.complete)view='report';save();render();$('#main').scrollIntoView({block:'start'});};
 if($('#back-evidence'))$('#back-evidence').onclick=()=>{doc=null;render();};
 ['restart','replay','mobile-restart'].forEach(id=>{if($('#'+id))$('#'+id).onclick=()=>confirmReset();});
 if($('#download-report'))$('#download-report').onclick=()=>download('credit-hire-coaching-report.md',reportText(),'text/markdown');
 if($('#print-report'))$('#print-report').onclick=()=>{document.querySelectorAll('details').forEach(d=>d.open=true);window.print();};
 if($('#export-config'))$('#export-config').onclick=()=>{try{download('credit-hire-scenario.json',JSON.stringify(readEditor(),null,2),'application/json');}catch(e){authorError(e);}};
 if($('#apply-config'))$('#apply-config').onclick=()=>{try{confirmReset(readEditor());}catch(e){authorError(e);}};
 if($('#restore-config'))$('#restore-config').onclick=async()=>{try{confirmReset(validateScenario(await(await fetch('./scenario.json')).json()));}catch(e){authorError(e);}};
 if($('#import-config'))$('#import-config').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error('Use a JSON file smaller than 1 MB.');const s=validateScenario(JSON.parse(await file.text()));$('#config-json').value=JSON.stringify(s,null,2);$('#config-title').value=s.title;$('#config-rate').value=s.dailyRate;toast('Imported into the editor. Apply to start a new attempt.');}catch(e){authorError(e);}};
}
function registerTools(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const controller=new AbortController();const list=[{name:'read_claim_state',description:'Read fictional claim progress and current decision options.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({stage:state.index,day:state.day,xp:state.xp,complete:state.complete,decision:state.complete?null:scenario.stages[state.index].title,options:state.complete?[]:(scenario.stages[state.index].options||[]).map(o=>({id:o.id,label:o.label}))})},{name:'open_claim_evidence',description:'Open an unlocked fictional artefact and mark it reviewed.',inputSchema:{type:'object',properties:{artifactId:{type:'string'}},required:['artifactId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{const a=scenario.artifacts.find(a=>a.id===input?.artifactId&&a.unlock<=state.index);if(!a)throw Error('Unknown or locked artefact');doc=a.id;view='evidence';if(!state.read.includes(doc))state.read.push(doc);save();render();return {title:a.title,body:artifactBody(a,{...state,rate:scenario.dailyRate})};}}];for(const tool of list){try{Promise.resolve(ctx.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
boot();
